CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, user_id TEXT UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','user')), group_id TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS learning_groups (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS topic_assignments (group_id TEXT NOT NULL REFERENCES learning_groups(id) ON DELETE CASCADE, topic_id TEXT NOT NULL, PRIMARY KEY(group_id,topic_id));
CREATE TABLE IF NOT EXISTS app_state (id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS progress (user_id TEXT NOT NULL, topic_id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(user_id,topic_id));
CREATE TABLE IF NOT EXISTS state_chunks (token TEXT NOT NULL, part INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(token,part));
